CREATE OR REPLACE TRIGGER "ECAMS".CMM0020_Trg
    BEFORE INSERT or UPDATE or DELETE ON CMM0020

FOR EACH ROW
Declare
   Cnt    Integer;

 Begin
   IF :NEW.CM_MACODE = 'POSITION' AND :NEW.CM_MICODE<>'****' THEN
      IF :NEW.CM_CLOSEDT IS NULL THEN
         SELECT COUNT(*)
           INTO Cnt
           FROM CMM0103
          WHERE CM_POSCD=:NEW.CM_MICODE;

         IF Cnt = 0 THEN
            INSERT INTO CMM0103 (CM_POSCD,CM_POSNAME,CM_SEQNO,CM_CREATDT,CM_LASTDT)
                VALUES
                (:NEW.CM_MICODE,:NEW.CM_CODENAME,9999,SYSDATE,SYSDATE);
         ELSE
            UPDATE CMM0103
               SET CM_POSNAME=:NEW.CM_CODENAME
             WHERE CM_POSCD=:NEW.CM_MICODE;
         END IF;
      ELSE
         UPDATE CMM0103
            SET CM_CLOSEDT=SYSDATE
          WHERE CM_POSCD=:NEW.CM_MICODE;
      END IF;
   End If;

End CMM0020_Trg;